<?php defined('ABSPATH') || exit; get_header(); $journal_path = sy3_personal() ? '/blog/' : '/journal/'; ?>
<main id="main"><header class="page-heading wrap"><p class="eyebrow">Практика автоматизации</p><h1><?php echo esc_html(is_search() ? 'Поиск: ' . get_search_query() : (is_home() ? (sy3_personal() ? 'Архив публикаций' : 'Журнал') : (is_post_type_archive('sy3_case') ? 'Работа в деталях' : (is_post_type_archive('sy3_service') ? 'Что можно автоматизировать' : get_the_archive_title())))); ?></h1><p class="lead"><?php echo esc_html(sy3_personal() ? 'Публикации предыдущей версии сайта. Актуальные разборы собраны в журнале Сутри.' : (is_post_type_archive('sy3_case') ? 'Исходная задача, принятые решения и границы подтверждённого результата.' : (is_post_type_archive('sy3_service') ? 'От конкретного узкого места — к понятной системе работы.' : 'Разбираю CRM, интеграции и ИИ через задачи бизнеса. С примерами, ограничениями и конкретными шагами.'))); ?></p>
<?php if (is_home() || is_search() || is_category()): ?><form role="search" class="search-form" method="get" action="<?php echo esc_url(home_url('/')); ?>"><label class="screen-reader-text" for="search-input">Что найти</label><input id="search-input" type="search" name="s" value="<?php echo esc_attr(get_search_query()); ?>" placeholder="Например: заявки, CRM или ИИ"><button class="button" type="submit">Найти ↗</button></form><div class="topic-links"><a href="<?php echo esc_url(home_url($journal_path)); ?>">Все материалы</a><?php foreach (get_categories(['hide_empty' => true]) as $cat): ?><a href="<?php echo esc_url(get_category_link($cat)); ?>"><?php echo esc_html($cat->name); ?></a><?php endforeach; ?></div><?php endif; ?></header>
<?php if (is_post_type_archive('sy3_case') || is_tax('sy3_case_topic')): ?><nav class="wrap topic-links case-topics" aria-label="Направления проектов"><a href="<?php echo esc_url(get_post_type_archive_link('sy3_case')); ?>"<?php if (is_post_type_archive('sy3_case')) echo ' aria-current="page"'; ?>>Все проекты</a><?php foreach (get_terms(['taxonomy' => 'sy3_case_topic', 'hide_empty' => true]) as $topic): ?><a href="<?php echo esc_url(get_term_link($topic)); ?>"<?php if (is_tax('sy3_case_topic', $topic->term_id)) echo ' aria-current="page"'; ?>><?php echo esc_html($topic->name); ?> · <?php echo (int) $topic->count; ?></a><?php endforeach; ?></nav><?php endif; ?>
<div class="wrap archive-grid card-grid<?php if (is_home() || is_category()) echo ' journal-archive'; ?>"><?php if (have_posts()): while (have_posts()): the_post(); sy3_post_card(get_post()); endwhile; else: ?><p>Материалов по этому запросу пока нет. Попробуйте другое слово или <a href="<?php echo esc_url(home_url($journal_path)); ?>">откройте <?php echo sy3_personal() ? 'архив' : 'журнал'; ?></a>.</p><?php endif; ?></div><div class="wrap pagination"><?php the_posts_pagination(['prev_text' => '← Назад', 'next_text' => 'Дальше →']); ?></div></main>
<?php get_footer(); ?>
